WITH valid AS (SELECT *, CASE WHEN txn_type IN ('REFUND', 'CREDIT') THEN 'Core' ELSE 'Other' END txn_type_group FROM transactions WHERE txn_time >= TIMESTAMP '2023-06-28 18:00:00' AND txn_time < '2023-09-01'), gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM valid), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT CASE WHEN amount >= 3100 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, COUNT(CASE WHEN merchant = 'Lazada' THEN 1 END) AS lazada_count, COUNT(*) FILTER (WHERE txn_type = 'DEBIT') AS debit_rows FROM sessions_transactions GROUP BY CASE WHEN amount >= 3100 THEN 'HIGH' ELSE 'LOW' END ORDER BY debit_rows DESC NULLS FIRST;
